"""The request records the layer types and writes.

Their types are generated from the SDK's own schema of each request
(`_requests.py`, `03-design/generated-requests.md`); these hold that every
one is reachable where a caller imports from, and that a request crosses
as JSON with a member written as its key however deep it sits.
"""

from __future__ import annotations

import json
import unittest
from pathlib import Path
from typing import Any

import teistro
from teistro import _requests, catalogue
from teistro.catalogue import Graha, Nakshatra

#: Generated by `cargo xtask gen ffi`: one example of every record's
#: request, every field written and a catalogue member wherever one stands.
DEEP = Path(__file__).resolve().parents[3] / "crates" / "sdk" / "tests" / "deep-requests.json"

#: Each catalogue kind's enum, by the kind a full key starts with.
KINDS = {kind: getattr(catalogue, name) for name, kind in catalogue._KINDS.items()}


def as_members(value: Any, found: list[str]) -> Any:
    """`value` with every full key a catalogue member of this build, as a
    caller would hand it: the enum member, not its spelling."""
    if isinstance(value, dict):
        return {key: as_members(inner, found) for key, inner in value.items()}
    if isinstance(value, list):
        return [as_members(inner, found) for inner in value]
    if isinstance(value, str) and "." in value:
        kind = KINDS.get(value.split(".", 1)[0])
        member = kind.by_key(value) if kind is not None else None
        if member is not None:
            found.append(value)
            return member
    return value


class TheRequests(unittest.TestCase):
    def test_every_generated_record_is_reachable_from_the_package(self) -> None:
        missing = [name for name in _requests.__all__ if not hasattr(teistro, name)]
        self.assertEqual(missing, [])

    def test_a_member_is_written_as_its_key_however_deep(self) -> None:
        asked = {"cycle": {"planet": Graha.JUPITER}, "rows": [{"star": Nakshatra.ROHINI}], "orbs": (1, 2)}
        written = teistro._record_json(asked, "asked", "{}")
        assert written is not None
        self.assertEqual(
            json.loads(written),
            {"cycle": {"planet": "graha.JUPITER"}, "rows": [{"star": "nakshatra.ROHINI"}], "orbs": [1, 2]},
        )

    def test_every_deep_example_with_its_members_as_enums_writes_back_as_itself(self) -> None:
        examples = json.loads(DEEP.read_text(encoding="utf-8"))
        found: list[str] = []
        for example in examples:
            request = example["request"]
            written = teistro._record_json(as_members(request, found), example["record"], "{}")
            assert written is not None
            self.assertEqual(json.loads(written), request, example["record"])
        # The members were handed as enums, so the check is the writer's.
        self.assertGreater(len(found), 100)

    def test_a_natal_point_is_written_as_an_answer_spells_it(self) -> None:
        points = [teistro.NatalPoint("LAGNA"), teistro.NatalPoint("GRAHA", Graha.MOON), "MOON"]
        written = teistro._record_json({"points": points}, "hits", "{}")
        assert written is not None
        self.assertEqual(
            json.loads(written)["points"],
            [{"point": "LAGNA"}, {"point": "GRAHA", "graha": "graha.MOON"}, "MOON"],
        )


if __name__ == "__main__":
    unittest.main()
